using System.Text.Json.Serialization;

namespace AutonomousAgentHub.Core.Contracts;

/// <summary>
/// Concrete code and test changes generated by <c>Stage4ExecutorAgent</c>.
/// </summary>
public sealed class Stage4ExecutionArtifact
{
    [JsonPropertyName("taskTitle")]
    public string TaskTitle { get; init; } = string.Empty;

    [JsonPropertyName("attemptNumber")]
    public int AttemptNumber { get; init; } = 1;

    [JsonPropertyName("implementationSummary")]
    public string ImplementationSummary { get; init; } = string.Empty;

    [JsonPropertyName("fileMutations")]
    public List<FileMutation> FileMutations { get; init; } = [];

    [JsonPropertyName("selfHealingNotes")]
    public string? SelfHealingNotes { get; init; }
}

/// <summary>
/// Full replacement content for a modified or newly created file in the target workspace.
/// </summary>
public sealed class FileMutation
{
    [JsonPropertyName("relativePath")]
    public string RelativePath { get; init; } = string.Empty;

    [JsonPropertyName("operation")]
    public string Operation { get; init; } = "Modify";

    [JsonPropertyName("updatedContent")]
    public string UpdatedContent { get; init; } = string.Empty;

    [JsonPropertyName("summaryOfChanges")]
    public string SummaryOfChanges { get; init; } = string.Empty;

    [JsonPropertyName("isTestFile")]
    public bool IsTestFile { get; init; }
}

